/* 학습 해설
 * ASN.1 Encoder·양수 Sign Byte와 Length 형식
 * 정수와 길이를 binary format에 기록할 때 부호 표시·최소 표현·buffer 공간을 고려해야 합니다.
 * Integer encoder는 음수를 거부하고 tag/length 공간을 확보한 뒤 leading zero byte를 생략합니다. 첫 유효 byte의 최상위 bit가 1이면 양수를 나타내기 위해 0byte를 앞에 붙입니다. 0은 한 zero byte로 기록합니다. Length helper는 127 이하 short form과 0x81/0x82/0x83 long form을 선택하며 0xffffff 초과를 거부합니다. 반환은 다음 write pointer 또는 ERR_PTR입니다.
 * 고정 source의 integer·length·OID encoder를 연결해 값 127/128과 길이 127/128을 각각 계산합니다. 값의 sign byte와 TLV length prefix는 다른 field이며 end_data capacity를 지켜야 합니다. 범용 ASN.1 전체 구현이라고 가정하지 않습니다.
 */
asn1_encode_integer(unsigned char *data, const unsigned char *end_data,
		    s64 integer)
{
	int data_len = end_data - data;
	unsigned char *d = &data[2];
	bool found = false;
	int i;

	if (WARN(integer < 0,
		 "BUG: integer encode only supports positive integers"))
		return ERR_PTR(-EINVAL);

	if (IS_ERR(data))
		return data;

	/* need at least 3 bytes for tag, length and integer encoding */
	if (data_len < 3)
		return ERR_PTR(-EINVAL);

	/* remaining length where at d (the start of the integer encoding) */
	data_len -= 2;

	data[0] = _tag(UNIV, PRIM, INT);
	if (integer == 0) {
		*d++ = 0;
		goto out;

