/* 학습 해설
 * PKCS7 Trust·Chain 교차와 방문 Cache
 * 메시지에 인증서를 넣었다는 사실만으로 신뢰가 생기지 않으며 미리 신뢰한 key까지 연결해야 합니다.
 * Trust 함수는 certificate seen을 초기화하고 SignedInfo별 chain을 검사합니다. Helper는 seen/verified 상태로 반복 검사를 줄이고 trusted keyring에서 certificate·root signer·직접 signer를 찾습니다. 알 수 없는 self-signed root는 ENOKEY입니다. Trusted key로 실제 signature를 verify하고 key_put하며 성공 경로에 verified를 표시합니다. Any chain 성공은 0이지만 검증 거부 등 강한 오류는 즉시 반환합니다.
 * 고정 source에서 trust_keyring·x509->signer·seen/verified를 그려 self-signed root와 등록된 anchor를 비교합니다. 메시지 안 인증서 목록과 시스템의 trusted keyring을 구분하고 chain 오류 우선순위·동일 certificate의 재방문을 확인합니다.
 */
int pkcs7_validate_trust(struct pkcs7_message *pkcs7,
			 struct key *trust_keyring)
{
	struct pkcs7_signed_info *sinfo;
	struct x509_certificate *p;
	int cached_ret = -ENOKEY;
	int ret;

	for (p = pkcs7->certs; p; p = p->next)
		p->seen = false;

	for (sinfo = pkcs7->signed_infos; sinfo; sinfo = sinfo->next) {
		ret = pkcs7_validate_trust_one(pkcs7, sinfo, trust_keyring);
		switch (ret) {
		case -ENOKEY:
			continue;
		case -ENOPKG:
			if (cached_ret == -ENOKEY)
				cached_ret = -ENOPKG;
			continue;
		case 0:
			cached_ret = 0;
			continue;
		default:
			return ret;
		}

