/* 학습 해설
 * LAPB·Data Link 연결 상태 기계
 * 신뢰성 있는 link layer는 연결 요청을 상태에 따라 처리하며 중복 요청과 이미 연결된 상태를 구분합니다.
 * LAPB connect request는 device별 control block을 얻고 없으면 BADTOKEN입니다. Lock 안에서 STATE_1이면 진행 중 요청으로 OK, STATE_3/4이면 CONNECTED를 반환합니다. 그 외에는 link establishment를 시작하고 STATE_1로 바꿉니다. 성공 반환은 handshake가 끝난 연결 확정이 아니라 요청 시작 또는 진행 상태일 수 있습니다.
 * 고정 LAPB source에서 state constants·lapb_establish_data_link·connect confirmation과 frame/timer 처리를 연결합니다. 실제 X.25/LAPB device support를 확인하고 API result code를 Linux errno 또는 TCP state 번호와 같은 enum으로 취급하지 않습니다.
 */
int lapb_connect_request(struct net_device *dev)
{
	struct lapb_cb *lapb = lapb_devtostruct(dev);
	int rc = LAPB_BADTOKEN;

	if (!lapb)
		goto out;

	spin_lock_bh(&lapb->lock);

	rc = LAPB_OK;
	if (lapb->state == LAPB_STATE_1)
		goto out_put;

	rc = LAPB_CONNECTED;
	if (lapb->state == LAPB_STATE_3 || lapb->state == LAPB_STATE_4)
		goto out_put;

	lapb_establish_data_link(lapb);

	lapb_dbg(0, "(%p) S0 -> S1\n", lapb->dev);
	lapb->state = LAPB_STATE_1;

	rc = LAPB_OK;
out_put:
	spin_unlock_bh(&lapb->lock);

