/* 학습 해설
 * Phonet Datagram·Address Family와 Headroom
 * 모뎀 관련 별도 address family도 socket flags·주소 구조·payload copy와 header 공간을 검증하는 계약을 가집니다.
 * Phonet send는 허용 msg flags 밖의 bit를 EOPNOTSUPP로 거부합니다. 목적 주소가 없으면 EDESTADDRREQ, 길이가 부족하면 EINVAL, family가 다르면 EAFNOSUPPORT입니다. MAX_PHONET_HEADER+payload를 할당하고 header 공간을 reserve한 뒤 message를 copy하여 pn_skb_send에 넘깁니다. 성공은 사용자 payload 길이를 반환합니다.
 * 고정 Phonet sockaddr 및 pn_skb_send·header 형식을 연결해 device/resource 주소를 읽습니다. IP sockaddr와 Phonet sockaddr를 같은 memory layout으로 넘기지 않고 실제 protocol/device support가 없는 환경에서는 validation branch부터 추적합니다.
 */
static int pn_sendmsg(struct sock *sk, struct msghdr *msg, size_t len)
{
	DECLARE_SOCKADDR(struct sockaddr_pn *, target, msg->msg_name);
	struct sk_buff *skb;
	int err;

	if (msg->msg_flags & ~(MSG_DONTWAIT|MSG_EOR|MSG_NOSIGNAL|
				MSG_CMSG_COMPAT))
		return -EOPNOTSUPP;

	if (target == NULL)
		return -EDESTADDRREQ;

	if (msg->msg_namelen < sizeof(struct sockaddr_pn))
		return -EINVAL;

	if (target->spn_family != AF_PHONET)
		return -EAFNOSUPPORT;

	skb = sock_alloc_send_skb(sk, MAX_PHONET_HEADER + len,
					msg->msg_flags & MSG_DONTWAIT, &err);
	if (skb == NULL)
		return err;
	skb_reserve(skb, MAX_PHONET_HEADER);

	err = memcpy_from_msg((void *)skb_put(skb, len), msg, len);

