/* 학습 해설
 * KCM·Message 누적과 Transport Multiplexing
 * 여러 연결을 메시지 단위로 사용하는 KCM에서는 stream byte 저장과 message 완료·queue 제출을 나눠 관리합니다.
 * KCM send는 tx mutex와 socket lock을 사용하고 seq_skb가 있으면 이전 미완성 message를 이어갑니다. DGRAM은 MORE가 없을 때, SEQPACKET은 EOR가 있을 때 message 완료입니다. Page frag를 병합하거나 frag_list를 추가하고 splice-pages 경로도 처리합니다. Complete message는 write queue로 넘기고 미완성은 seq_skb에 저장합니다. 이미 copy한 SEQPACKET byte는 뒤 오류 때 partial success로 보존할 수 있습니다.
 * 고정 KCM과 strparser/BPF parse·attach transport 경로를 연결합니다. Send flags에 따른 message 경계·copy byte 수·page 참조·후속 transport write error를 구분하고 request 한 번이 message 하나로 고정되는 것이 아닌 mode를 확인합니다.
 */
static int kcm_sendmsg(struct socket *sock, struct msghdr *msg, size_t len)
{
	struct sock *sk = sock->sk;
	struct kcm_sock *kcm = kcm_sk(sk);
	struct sk_buff *skb = NULL, *head = NULL;
	size_t copy, copied = 0;
	long timeo = sock_sndtimeo(sk, msg->msg_flags & MSG_DONTWAIT);
	int eor = (sock->type == SOCK_DGRAM) ?
		  !(msg->msg_flags & MSG_MORE) : !!(msg->msg_flags & MSG_EOR);
	int err = -EPIPE;

	mutex_lock(&kcm->tx_mutex);
	lock_sock(sk);

	/* Per tcp_sendmsg this should be in poll */
	sk_clear_bit(SOCKWQ_ASYNC_NOSPACE, sk);

	if (sk->sk_err)
		goto out_error;

	if (kcm->seq_skb) {
		/* Previously opened message */
		head = kcm->seq_skb;
		skb = kcm_tx_msg(head)->last_skb;
		goto start;
	}

