/* 학습 해설
 * BATMAN Adv·Next Hop·Fragment와 Network Coding
 * Mesh 송신은 최종 originator와 실제 next-hop neighbour를 구분하고 각 선택 경로에서 packet 소유권을 정리합니다.
 * 함수는 originator의 router neighbour를 찾아 참조를 얻습니다. 없으면 skb를 free하고 EINVAL입니다. Fragmentation이 켜지고 packet이 incoming interface MTU를 넘으면 fragment helper가 packet을 소비합니다. Forwarded packet은 network coding을 시도해 성공이면 EINPROGRESS, 아니면 unicast로 보냅니다. 모든 전달 경로 뒤 skb=NULL로 하고 neighbour 참조를 put합니다.
 * 고정 BATMAN Adv의 routing algorithm·originator/neighbor·translation table과 fragmentation/network coding source를 연결합니다. 실제 mesh interface config와 capability를 확인하고 다음 hop 선택·최종 host 주소 변환·비동기 coding queue를 분리합니다.
 */
int batadv_send_skb_to_orig(struct sk_buff *skb,
			    struct batadv_orig_node *orig_node,
			    struct batadv_hard_iface *recv_if)
{
	struct batadv_priv *bat_priv = orig_node->bat_priv;
	struct batadv_neigh_node *neigh_node;
	int ret;

	/* batadv_find_router() increases neigh_nodes refcount if found. */
	neigh_node = batadv_find_router(bat_priv, orig_node, recv_if);
	if (!neigh_node) {
		ret = -EINVAL;
		goto free_skb;
	}

	/* Check if the skb is too large to send in one piece and fragment
	 * it if needed.
	 */
	if (atomic_read(&bat_priv->fragmentation) &&
	    skb->len > neigh_node->if_incoming->net_dev->mtu) {
		/* Fragment and send packet. */
		ret = batadv_frag_send_packet(skb, orig_node, neigh_node);
		/* skb was consumed */
		skb = NULL;

		goto put_neigh_node;

