/* 학습 해설
 * 정수 Sqrt·Shift-and-Subtract
 * 부동소수점 없이 정수 제곱근의 바닥값을 얻는 과정에서 두 bit씩 처리하는 알고리즘을 봅니다.
 * 입력 0/1은 그대로 반환합니다. 가장 높은 set bit 위치를 짝수 위치로 맞춰 m을 시작하고 b=y+m과 입력을 비교합니다. Y를 한 bit shift한 뒤 충분하면 x에서 b를 빼고 y에 m을 더하며 m을 두 bit씩 내립니다. 반환은 floor(sqrt(x))입니다. 32bit long 구성의 int_sqrt64는 작은 입력에 기본 함수, 큰 u64에는 대응 loop를 사용합니다.
 * 고정 source에서 x=15/16/17의 결과를 비교하고 __fls·m>>=2·y 갱신을 표로 읽습니다. unsigned long 폭과 입력 함수 선택을 확인하며 real-valued sqrt의 소수 부분을 보존하는 API로 사용하지 않습니다.
 */
unsigned long int_sqrt(unsigned long x)
{
	unsigned long b, m, y = 0;

	if (x <= 1)
		return x;

	m = 1UL << (__fls(x) & ~1UL);
	while (m != 0) {
		b = y + m;
		y >>= 1;

		if (x >= b) {
			x -= b;
			y += m;
		}
		m >>= 2;
	}

	return y;
}
EXPORT_SYMBOL(int_sqrt);

