/* 학습 해설
 * 정수 다항식·계수와 분모 재배치
 * 온도 센서의 측정값과 온도 사이의 다항식 변환을 부동소수점 없이 구현하는 실제 방법을 배웁니다.
 * 각 항은 차수 deg, 계수 coef, 반복마다 나눌 divider, 마지막에 나눌 divider_leftover로 표현합니다. tmp를 계수로 시작하고 차수만큼 mult_frac(tmp,data,divider)를 적용한 뒤 나머지 분모로 나눈 값을 합합니다. 차수가 0인 상수항을 처리하면 종료합니다. 합을 total_divider로 나누되 이 값이 0이면 코드가 1을 사용합니다. 각 중간 나눗셈의 정수 절단 때문에 실수 다항식을 마지막에 한 번 반올림하는 계산과 다를 수 있습니다.
 * include/linux/polynomial.h의 구조체와 센서 변환 예의 단위 mC를 함께 읽습니다. 작은 예 2x²+3x+4를 차수 2·1·0의 항으로 만들고 모든 분모를 1로 놓아 x=5를 대입합니다. 상수항 종료 표식, 0이 아닌 항별 분모, long 중간값 범위를 호출자가 보장해야 합니다.
 */
long polynomial_calc(const struct polynomial *poly, long data)
{
	const struct polynomial_term *term = poly->terms;
	long total_divider = poly->total_divider ?: 1;
	long tmp, ret = 0;
	int deg;

	/*
	 * Here is the polynomial calculation function, which performs the
	 * redistributed terms calculations. It's pretty straightforward.
	 * We walk over each degree term up to the free one, and perform
	 * the redistributed multiplication of the term coefficient, its
	 * divider (as for the rationale fraction representation), data
	 * power and the rational fraction divider leftover. Then all of
	 * this is collected in a total sum variable, which value is
	 * normalized by the total divider before being returned.
	 */
	do {
		tmp = term->coef;
		for (deg = 0; deg < term->deg; ++deg)
			tmp = mult_frac(tmp, data, term->divider);
		ret += tmp / term->divider_leftover;
	} while ((term++)->deg);

	return ret / total_divider;
}

