/* 학습 해설
 * ELF Build ID·실행 파일과 기호 자료 연결
 * 스택 주소를 올바른 빌드의 기호 자료와 연결하려면 파일 이름보다 실제 빌드 식별자가 필요한 이유를 익힙니다.
 * 메모리 버퍼 API는 ELF 전체가 아니라 note 구간을 parse_build_id에 넘깁니다. Note는 헤더 뒤 이름과 descriptor를 각각 4바이트 정렬하며, type=3·이름 크기 4·GNU와 종료 NUL·양수이고 최대 크기 이하인 descriptor를 요구합니다. 식별자를 복사하고 출력 버퍼의 나머지를 0으로 채웁니다. 파일 매핑 API는 ELF magic·ET_EXEC/ET_DYN·32/64bit class를 확인하고 최대 256개 program header의 PT_NOTE를 찾습니다. nofault API는 필요한 파일 자료가 캐시에 없을 때 읽어 들이기 위해 잠들지 않습니다.
 * 읽기 전용 ELF의 note를 도구로 관찰한 후 이름 길이·descriptor 길이·정렬된 다음 note 위치를 계산합니다. 버퍼 API와 VMA 기반 API의 입력을 구분하고 출력은 BUILD_ID_SIZE_MAX만큼 확보합니다. 같은 이름의 실행 파일이 교체됐을 때 분석할 기호 파일의 Build ID와 대조합니다.
 */
int build_id_parse_buf(const void *buf, unsigned char *build_id, u32 buf_size)
{
	struct freader r;
	int err;

	freader_init_from_mem(&r, buf, buf_size);

	err = parse_build_id(&r, build_id, NULL, 0, buf_size);

	freader_cleanup(&r);
	return err;
}

#if IS_ENABLED(CONFIG_STACKTRACE_BUILD_ID) || IS_ENABLED(CONFIG_VMCORE_INFO)
unsigned char vmlinux_build_id[BUILD_ID_SIZE_MAX] __ro_after_init;

/**
 * init_vmlinux_build_id - Compute and stash the running kernel's build ID
 */
void __init init_vmlinux_build_id(void)
{
	extern const void __start_notes;
	extern const void __stop_notes;
	unsigned int size = &__stop_notes - &__start_notes;

	build_id_parse_buf(&__start_notes, vmlinux_build_id, size);

