/* 학습 해설
 * Memcat Pointer·종료 표식 배열 결합
 * 포인터 배열을 합치는 것과 포인터가 가리키는 객체를 복제하는 것의 차이를 실제 할당 helper로 익힙니다.
 * 두 입력 배열을 NULL까지 순회해 원소 수를 세고 마지막 종료 NULL 하나를 더한 크기로 kmalloc_array를 호출합니다. 새 배열은 뒤에서부터 채웁니다. 처음에는 b의 마지막 NULL을 복사하고 b의 원소를 거꾸로 복사하다 b의 첫 위치에 도달하면 a의 대응 위치로 전환합니다. 반환 배열의 순서는 a 원소 다음 b 원소이며 실패하면 NULL입니다. 새로 할당하는 것은 포인터 저장 공간이고 대상 객체나 그 참조 횟수는 복제하지 않습니다.
 * a=[A,B,NULL], b=[C,NULL] 예에서 nr와 p의 이동을 표로 적고 결과 [A,B,C,NULL]을 확인합니다. 각 입력은 읽을 수 있는 NULL 종료 배열이어야 하며 입력 배열 자체를 NULL 포인터로 넘기는 계약은 없습니다. GFP_KERNEL 할당 문맥과 새 배열의 해제 책임을 호출자에서 확인합니다.
 */
void **__memcat_p(void **a, void **b)
{
	void **p = a, **new;
	int nr;

	/* count the elements in both arrays */
	for (nr = 0, p = a; *p; nr++, p++)
		;
	for (p = b; *p; nr++, p++)
		;
	/* one for the NULL-terminator */
	nr++;

	new = kmalloc_array(nr, sizeof(void *), GFP_KERNEL);
	if (!new)
		return NULL;

	/* nr -> last index; p points to NULL in b[] */
	for (nr--; nr >= 0; nr--, p = p == b ? &a[nr] : p - 1)
		new[nr] = *p;

	return new;
}
EXPORT_SYMBOL_GPL(__memcat_p);

