/* 학습 해설
 * MMIO Signature·장치 주소의 순차 읽기
 * 장치의 메모리 매핑 주소를 일반 RAM 문자열과 동일하게 다루지 않고 I/O 접근 함수를 쓰는 이유를 배웁니다.
 * ioremap으로 마련한 io_addr에서 readb로 한 바이트씩 읽어 signature의 바이트와 비교합니다. 다르면 즉시 0이고 길이만큼 모두 같으면 1입니다. 포인터는 두 쪽 모두 한 바이트씩 증가합니다. 암호학적 전자서명 검증이 아니라 BIOS 등의 고정 바이트 패턴 일치 검사입니다. 함수에는 mapping 생성·해제나 길이 범위 확인이 없으며 length=0은 읽지 않고 1을 반환합니다.
 * 실제 하드웨어에 쓰기 실험을 하지 않고 원본의 readb와 __iomem 표식을 읽습니다. 호출자가 준비한 mapping 길이 안에서 음수가 아닌 length와 읽을 수 있는 signature를 제공해야 합니다. ioremap 수명과 장치의 읽기 부작용은 해당 호출 문맥에서 확인합니다.
 */
int check_signature(const volatile void __iomem *io_addr,
			const unsigned char *signature, int length)
{
	while (length--) {
		if (readb(io_addr) != *signature)
			return 0;
		io_addr++;
		signature++;
	}
	return 1;
}
EXPORT_SYMBOL(check_signature);

