/* 학습 해설
 * Atomic Dec-and-Lock·마지막 참조와 잠금
 * 참조 수가 0이 되는 순간과 객체 정리용 잠금 획득 사이에 틈이 생기지 않도록 연결하는 helper를 읽습니다.
 * atomic_add_unless는 현재 값이 1이면 감소하지 않고 느린 경로로 갑니다. 그 밖의 정상 참조 값에서는 1을 감소시키고 잠금 없이 0을 반환합니다. 느린 경로는 먼저 lock을 잡은 다음 atomic_dec_and_test로 감소합니다. 결과가 0이면 잠금을 가진 채 1을 반환하고, 그 사이 참조가 증가해 아직 0이 아니면 잠금을 풀고 0을 반환합니다. 단순히 먼저 0으로 감소시킨 뒤 lock을 잡는 순서와 같은 동작이 아닙니다.
 * 호출자가 유효한 양수 참조를 보유하고 다른 참조 획득·객체 제거가 같은 수명 규칙을 따르는지 읽습니다. 1 반환은 성공 상태와 함께 잠금 해제 책임을 넘깁니다. irqsave 변형의 flags와 raw spinlock 변형은 해당 문맥에 맞춰 사용하며 atomic_t를 모든 안전 검사를 갖춘 refcount_t로 혼동하지 않습니다.
 */
int _atomic_dec_and_lock(atomic_t *atomic, spinlock_t *lock)
{
	/* Subtract 1 from counter unless that drops it to 0 (ie. it was 1) */
	if (atomic_add_unless(atomic, -1, 1))
		return 0;

	/* Otherwise do it the slow way */
	spin_lock(lock);
	if (atomic_dec_and_test(atomic))
		return 1;
	spin_unlock(lock);
	return 0;
}

