/* 학습 해설
 * Do Once·일회 실행과 Static Key 해제
 * 여러 CPU가 동시에 처음 호출하더라도 초기화를 한 번만 수행하고 나중의 경로 비용을 줄이는 두 장치를 배웁니다.
 * start는 IRQ 상태를 저장하며 전역 spinlock을 잡고 done을 확인합니다. 이미 끝났으면 풀고 false, 아니면 잠금을 가진 채 true를 반환합니다. done helper는 done=true를 기록하고 lock과 IRQ 상태를 복원한 뒤 work를 예약해 static branch를 비활성화합니다. 작업 공간 할당이 실패해도 done은 이미 true이므로 재실행을 막는 정확성은 유지되지만 분기 최적화는 늦춰집니다. sleepable 변형은 별도 mutex를 사용합니다.
 * include/linux/once.h의 DO_ONCE와 DO_ONCE_SLEEPABLE 호출 경로를 함께 읽습니다. 일반 변형의 본체는 IRQ가 꺼진 spinlock 보유 문맥이므로 잠드는 작업을 넣지 않습니다. sleepable 변형은 잠들 수 있는 호출 문맥에서 사용합니다. 직접 start만 호출하고 done을 빼먹으면 잠금을 보유하게 되는 계약을 확인합니다.
 */
bool __do_once_start(bool *done, unsigned long *flags)
	__acquires(once_lock)
{
	spin_lock_irqsave(&once_lock, *flags);
	if (*done) {
		spin_unlock_irqrestore(&once_lock, *flags);
		/* Keep sparse happy by restoring an even lock count on
		 * this lock. In case we return here, we don't call into
		 * __do_once_done but return early in the DO_ONCE() macro.
		 */
		__acquire(once_lock);
		return false;
	}

	return true;
}
EXPORT_SYMBOL(__do_once_start);

void __do_once_done(bool *done, struct static_key_true *once_key,
		    unsigned long *flags, struct module *mod)
	__releases(once_lock)
{
	*done = true;
	spin_unlock_irqrestore(&once_lock, *flags);
	once_disable_jump(once_key, mod);
}

