/* 학습 해설
 * Ratelimit·메시지 폭주와 구간별 허용량
 * 오류가 반복될 때 로그 자체가 CPU와 출력 장치를 압도하지 않도록 메시지의 허용 여부를 정하는 실제 helper를 읽습니다.
 * interval이 0이면 제한 없이 1을 반환합니다. 그 외에는 raw_spin_trylock_irqsave로 상태 잠금을 시도하고 실패하면 기다리지 않고 0을 반환합니다. begin과 interval의 합이 현재 jiffies보다 이전이면 구간을 새로 시작하고 printed를 0으로 초기화합니다. burst가 0이 아니며 printed보다 클 때만 printed를 증가시키고 1을 반환합니다. 나머지는 missed를 증가시키고 0입니다. 토큰을 시간에 비례해 연속 충전하는 token bucket과 다른 구간 기반 구현입니다.
 * 사용자별 ratelimit_state를 준비하고 반환 1일 때만 해당 메시지 작업을 수행합니다. interval의 jiffies 단위와 burst의 횟수를 구분하고 같은 state를 공유하면 허용량도 공유됨을 확인합니다. 설정을 READ_ONCE로 각각 읽어도 두 값이 하나의 원자적 설정 묶음이 되는 것은 아닙니다.
 */
int ___ratelimit(struct ratelimit_state *rs, const char *func)
{
	/* Paired with WRITE_ONCE() in .proc_handler().
	 * Changing two values seperately could be inconsistent
	 * and some message could be lost.  (See: net_ratelimit_state).
	 */
	int interval = READ_ONCE(rs->interval);
	int burst = READ_ONCE(rs->burst);
	unsigned long flags;
	int ret;

	if (!interval)
		return 1;

	/*
	 * If we contend on this state's lock then almost
	 * by definition we are too busy to print a message,
	 * in addition to the one that will be printed by
	 * the entity that is holding the lock already:
	 */
	if (!raw_spin_trylock_irqsave(&rs->lock, flags))
		return 0;

	if (!rs->begin)
		rs->begin = jiffies;

