/* 학습 해설
 * CPU Rmap·IRQ Affinity의 역방향 탐색
 * IRQ가 어느 CPU에 배정되는지뿐 아니라 현재 CPU에서 가까운 IRQ 객체를 고르는 반대 방향의 정보가 필요한 경우를 배웁니다.
 * rmap은 각 CPU에 가까운 객체 index와 distance를 저장합니다. 특정 객체의 affinity가 바뀌면 그 객체를 가리키던 online CPU의 거리를 무한대로 지우고 새 affinity CPU는 해당 index·거리 0으로 지정합니다. 그 NUMA node의 CPU를 갱신 대상으로 추가하고 sibling·core·같은 node 이웃 순으로 거리 1·2·3 후보를 복사합니다. 임의 NUMA node 사이 거리까지 탐색하지는 않습니다. IRQ notifier는 workqueue에서 이 갱신을 호출합니다.
 * 객체 수가 1 이상이고 u16 index 범위 안인 rmap을 할당하고 객체를 등록한 뒤 affinity 변경을 반영합니다. alloc의 size>65535 검사만 보고 size=0도 안전하다고 생각하지 않습니다. 초기 index 계산에 cpu%size가 있습니다. IRQ rmap은 할당된 IRQ를 request_irq로 묶기 전에 notifier를 붙이고 IRQ 해제 전에 process context에서 정리합니다.
 */
int cpu_rmap_update(struct cpu_rmap *rmap, u16 index,
		    const struct cpumask *affinity)
{
	cpumask_var_t update_mask;
	unsigned int cpu;

	if (unlikely(!zalloc_cpumask_var(&update_mask, GFP_KERNEL)))
		return -ENOMEM;

	/* Invalidate distance for all CPUs for which this used to be
	 * the nearest object.  Mark those CPUs for update.
	 */
	for_each_online_cpu(cpu) {
		if (rmap->near[cpu].index == index) {
			rmap->near[cpu].dist = CPU_RMAP_DIST_INF;
			cpumask_set_cpu(cpu, update_mask);
		}
	}

	debug_print_rmap(rmap, "after invalidating old distances");

	/* Set distance to 0 for all CPUs in the new affinity mask.
	 * Mark all CPUs within their NUMA nodes for update.
	 */
	for_each_cpu(cpu, affinity) {
		rmap->near[cpu].index = index;

