/* 학습 해설
 * LWQ·Lockless Enqueue와 FIFO 소비
 * IRQ나 bottom-half에서 작업을 넣고 별도 thread에서 순서대로 처리하는 경량 큐의 생산·소비 구조를 익힙니다.
 * 새 항목은 new llist의 head에 잠금 없이 들어가므로 그 목록은 삽입 순서의 반대입니다. 소비자는 spinlock 아래 ready 목록에서 하나를 꺼냅니다. ready가 비면 new를 통째로 분리하고 reverse_order로 뒤집어 오래된 항목부터 꺼내도록 합니다. 이 전환 중에는 ready에 임시 값 1을 release store하여 empty 검사에서 잠깐 빈 큐처럼 보이지 않게 합니다. dequeue_all은 기존 ready 뒤에 뒤집은 new를 연결합니다. lockless인 부분과 소비자 잠금 부분의 역할이 다릅니다.
 * 객체에 lwq_node를 넣고 lwq_init 후 enqueue합니다. enqueue의 true는 큐가 이전에 비었을 가능성을 나타내므로 대기 thread를 깨우는 데 사용합니다. dequeue는 항상 동일한 호출 문맥에서 실행하도록 header 계약을 따르고 반환 객체의 소유권·해제 시점을 정합니다. 같은 node를 큐 안에 있는 동안 다시 넣지 않습니다.
 */
struct llist_node *__lwq_dequeue(struct lwq *q)
{
	struct llist_node *this;

	if (lwq_empty(q))
		return NULL;
	spin_lock(&q->lock);
	this = q->ready;
	if (!this && !llist_empty(&q->new)) {
		/* ensure queue doesn't appear transiently lwq_empty */
		smp_store_release(&q->ready, (void *)1);
		this = llist_reverse_order(llist_del_all(&q->new));
		if (!this)
			q->ready = NULL;
	}
	if (this)
		q->ready = llist_next(this);
	spin_unlock(&q->lock);
	return this;
}
EXPORT_SYMBOL_GPL(__lwq_dequeue);

/**
 * lwq_dequeue_all - dequeue all currently enqueued objects
 * @q:	the queue to dequeue from
 *
 * Remove and return a linked list of llist_nodes of all the objects that were
 * in the queue. The first on the list will be the object that was least
 * recently enqueued.
 */

