/* 학습 해설
 * Closure·미완료 작업 참조와 Continuation
 * 여러 비동기 I/O가 끝난 다음 작업을 실행하려면 호출 스택을 계속 붙잡는 대신 미완료 참조와 다음 함수를 연결할 수 있습니다.
 * closure는 실행 중인 주체의 참조 1과 제출한 비동기 작업의 참조를 셉니다. 각 작업 전 get, 완료 시 put을 대응시키고 continue_at은 다음 함수를 설정한 뒤 실행 주체의 참조와 RUNNING bit를 놓습니다. 낮은 비트의 남은 참조가 0이 되면 다음 함수가 있으면 참조를 다시 1로 초기화해 queue하거나 직접 호출합니다. 종료·destructor 경로는 부모 참조를 놓습니다. remaining에는 참조 수뿐 아니라 WAITING·RUNNING·DESTRUCTOR 상태가 함께 들어 있으므로 정수 전체를 그대로 작업 수로 읽지 않습니다.
 * closure_init 뒤 두 I/O에 각각 get을 하고 완료 callback에서 put을 합니다. continue_at 뒤에는 즉시 return하여 이미 소유권을 놓은 자료를 만지지 않습니다. workqueue=NULL이면 마지막 put의 문맥에서 다음 함수가 직접 실행될 수 있습니다. 잠드는 동기 대기는 해당 process context에서 closure_sync로 처리합니다.
 */
void closure_put(struct closure *cl)
{
	closure_put_after_sub(cl, atomic_dec_return_release(&cl->remaining));
}
EXPORT_SYMBOL(closure_put);

/*
 * closure_wake_up - wake up all closures on a wait list, without memory barrier
 */
void __closure_wake_up(struct closure_waitlist *wait_list)
{
	struct llist_node *list;
	struct closure *cl, *t;
	struct llist_node *reverse = NULL;

	list = llist_del_all(&wait_list->list);

	/* We first reverse the list to preserve FIFO ordering and fairness */
	reverse = llist_reverse_order(list);

	/* Then do the wakeups */
	llist_for_each_entry_safe(cl, t, reverse, list) {
		closure_set_waiting(cl, 0);
		closure_sub(cl, CLOSURE_WAITING + 1);
	}
}

