/* 학습 해설
 * Objagg·Root와 Delta로 객체 공유
 * 장치의 제한된 하드웨어 자원을 객체마다 중복해서 만들기보다 공통 root와 작은 차이로 표현하는 집계 기술을 배웁니다.
 * 객체 바이트를 키로 rhashtable에서 먼저 찾습니다. 같으면 기존 객체 참조를 늘립니다. 새 객체면 hints를 먼저 사용하고 없거나 적용할 수 없으면 기존 root에서 delta_create를 시도합니다. 가능한 root가 없으면 root_create로 독립 root를 만듭니다. 현재 구조는 root와 leaf delta의 두 단계이며 delta를 다시 부모로 삼는 중첩은 지원하지 않습니다. Delta는 부모 참조를 보유하고 마지막 put에서 delta_destroy와 부모 put을 연결합니다.
 * obj_size와 root_create/destroy·delta_check/create/destroy callback을 제공하여 objagg를 생성합니다. get 성공과 ERR_PTR를 구분하고 put을 대응시킵니다. 바이트 키에 padding 등 불안정한 값이 들어가지 않도록 표현을 정합니다. 모든 잠금은 호출자가 제공하며 root/delta의 하드웨어 의미도 callback의 계약에 달려 있습니다.
 */
struct objagg_obj *objagg_obj_get(struct objagg *objagg, void *obj)
{
	struct objagg_obj *objagg_obj;

	objagg_obj = __objagg_obj_get(objagg, obj);
	if (IS_ERR(objagg_obj))
		return objagg_obj;
	objagg_obj_stats_inc(objagg_obj);
	trace_objagg_obj_get(objagg, objagg_obj, objagg_obj->refcount);
	return objagg_obj;
}
EXPORT_SYMBOL(objagg_obj_get);

static void objagg_obj_destroy(struct objagg *objagg,
			       struct objagg_obj *objagg_obj)
{
	trace_objagg_obj_destroy(objagg, objagg_obj);
	--objagg->obj_count;
	list_del(&objagg_obj->list);
	rhashtable_remove_fast(&objagg->obj_ht, &objagg_obj->ht_node,
			       objagg->ht_params);
	objagg_obj_fini(objagg, objagg_obj);
	kfree(objagg_obj);
}

