/* 학습 해설
 * IRQ Poll·완료 Budget와 Softirq 순환
 * 장치 완료마다 IRQ 처리 부담이 커질 때 완료 작업을 제한된 budget으로 묶어 처리하는 블록 계층 관련 polling framework를 익힙니다.
 * sched는 DISABLE 상태를 거부하고 SCHED bit를 원자적으로 세워 중복 등록을 막은 뒤 CPU별 목록 tail에 넣고 softirq를 올립니다. Softirq는 전체 budget 256과 시작 jiffies를 확인하고 각 poll callback에 weight를 줍니다. 처리량을 전체 budget에서 빼며 weight 이상 처리한 항목은 tail로 옮겨 순환하거나 disable 요청이면 완료시킵니다. 전체 budget이나 시간 구간이 끝나면 softirq를 다시 예약합니다. 적게 처리해 끝난 callback은 irq_poll_complete로 목록과 SCHED를 정리하는 계약을 따릅니다.
 * driver의 irq_poll_init weight와 callback을 함께 읽고 처리량 반환·complete·IRQ 재활성화가 맞물리는 위치를 찾습니다. softirq callback에서 process context처럼 잠들지 않습니다. irq_poll_disable은 msleep으로 진행 중 callback 종료를 기다리므로 별도 호출 문맥이 필요하며 enable은 자동 poll 실행을 예약하지 않습니다.
 */
void irq_poll_sched(struct irq_poll *iop)
{
	unsigned long flags;

	if (test_bit(IRQ_POLL_F_DISABLE, &iop->state))
		return;
	if (test_and_set_bit(IRQ_POLL_F_SCHED, &iop->state))
		return;

	local_irq_save(flags);
	list_add_tail(&iop->list, this_cpu_ptr(&blk_cpu_iopoll));
	raise_softirq_irqoff(IRQ_POLL_SOFTIRQ);
	local_irq_restore(flags);
}
EXPORT_SYMBOL(irq_poll_sched);

