/* 학습 해설
 * Substring 숫자 변환·기수와 완전 소비
 * 이미 잘라 놓은 문자열도 어떤 숫자 변환 API를 고르는지에 따라 허용 형식과 오류 검사 수준이 달라집니다.
 * match_strlcpy는 from/to 사이를 크기 제한 버퍼에 복사하고 NUL을 붙이되 반환은 실제 원본 길이입니다. 숫자 helper는 24바이트 버퍼에 너무 긴 범위가 들어오면 ERANGE입니다. match_int는 match_number에 base=0을 넘겨 자동 기수를 쓰고 숫자를 하나라도 읽었는지와 int 범위를 확인하지만 endp가 문자열 끝인지 확인하지 않습니다. match_uint는 kstrtouint의 base=10을 사용하고 match_u64는 kstrtoull의 base=0을 사용합니다. 이름·주석만으로 모두 decimal 또는 동일한 strict parser라고 판단할 수 없습니다.
 * 원하는 숫자 정책에 맞는 signed·unsigned·기수 helper를 골라 반환 0과 EINVAL/ERANGE를 처리합니다. 독립 substring이 12junk이면 match_int는 접두 숫자를 받아들일 수 있으므로 앞의 패턴 검사나 별도 완전 소비 조건을 연결합니다. match_strdup이 필요하면 별도 문자열을 할당하고 나중에 kfree합니다.
 */
int match_int(substring_t *s, int *result)
{
	return match_number(s, result, 0);
}
EXPORT_SYMBOL(match_int);

/**
 * match_uint - scan a decimal representation of an integer from a substring_t
 * @s: substring_t to be scanned
 * @result: resulting integer on success
 *
 * Description: Attempts to parse the &substring_t @s as a decimal integer.
 *
 * Return: On success, sets @result to the integer represented by the string
 * and returns 0. Returns -EINVAL or -ERANGE on failure.
 */
int match_uint(substring_t *s, unsigned int *result)
{
